{
  "contractVersion": "references-v2",
  "title": "大模型基础概念题组",
  "reason": null,
  "materialPlan": [
    {
      "material": 1,
      "contribution": "六段正文覆盖token、训练与推理、RAG与微调、程序与workflow、Agent与工具、三者关系，独有考点充足。本组按reviewContract只考查concept角色，选取r1/r2的token与参数更新混淆点、r4/r5的程序与Agent概念边界、r6的三者关系，共3题。",
      "references": ["r1", "r2", "r4", "r5", "r6"]
    }
  ],
  "items": [
    {
      "focus": "区分token单位与参数更新的基本概念，识别常见误解",
      "scenario": null,
      "stem": "关于大语言模型的token和训练参数调整，以下哪项符合课程表述？",
      "kind": "concept",
      "stemEvidenceIds": ["r1"],
      "options": [
        {
          "id": "A",
          "text": "token是模型处理文本的单位，可以是一个字、词的一部分或其他片段，不能简单等同于一个汉字或一个英文单词。",
          "reasonParts": [
            {
              "text": "该表述与r1一致：token是模型处理文本的单位，可以是一个字、词的一部分或其他片段，不能简单等同于一个汉字或一个英文单词。",
              "evidenceIds": ["r1"]
            }
          ]
        },
        {
          "id": "B",
          "text": "一个token必定对应一个完整汉字或一个完整英文单词。",
          "reasonParts": [
            {
              "text": "该表述错误，因为r1明确指出token可以是字、词的一部分或其他片段，不能简单等同于一个汉字或一个英文单词。",
              "evidenceIds": ["r1"]
            }
          ]
        },
        {
          "id": "C",
          "text": "训练阶段依据数据和损失函数调整模型参数，训练完成后的参数保存了从数据中学习到的统计规律。",
          "reasonParts": [
            {
              "text": "该表述与r1一致：训练阶段依据数据和损失函数调整模型参数，训练完成后的参数保存了从数据中学习到的统计规律。",
              "evidenceIds": ["r1"]
            }
          ]
        },
        {
          "id": "D",
          "text": "参数数量多就意味着每两次回答都正确且掌握最新信息。",
          "reasonParts": [
            {
              "text": "该表述错误，因为r1指出参数数量多不等于每次回答都正确，也不等于模型掌握最新信息。",
              "evidenceIds": ["r1"]
            }
          ]
        }
      ],
      "correctOptionId": "A",
      "reviewCheck": {
        "objectiveIds": ["llm-theory-practice"],
        "role": "concept",
        "rationale": "本题直接检查学生是否理解token是文本处理单位，而不是固定等于一个汉字或英文单词，并同时检查训练阶段参数调整的基本含义。这对应llm-theory-practice目标中concept角色要求的区分token、训练参数调整等基础概念并识别常见误解。r1是本题全部选项依据的来源段，与目标sourceReferenceIds相交。"
      }
    },
    {
      "focus": "区分推理阶段是否更新参数与普通聊天是否属于重新训练",
      "scenario": null,
      "stem": "关于推理、上下文与提示，以下哪项符合课程表述？",
      "kind": "concept",
      "stemEvidenceIds": ["r2"],
      "options": [
        {
          "id": "A",
          "text": "推理阶段使用模型和当前输入生成输出；普通对话中的一次提问通常不会自动更新模型参数。",
          "reasonParts": [
            {
              "text": "该表述与r2一致：推理阶段使用模型和当前输入生成输出；普通对话中的一次提问通常不会自动更新模型参数。",
              "evidenceIds": ["r2"]
            }
          ]
        },
        {
          "id": "B",
          "text": "普通对话中的一次提问通常会自动更新模型参数，因此属于重新训练。",
          "reasonParts": [
            {
              "text": "该表述错误，因为r2明确说普通对话中的一次提问通常不会自动更新模型参数。",
              "evidenceIds": ["r2"]
            }
          ]
        },
        {
          "id": "C",
          "text": "提示词、历史对话、检索到的资料和工具返回可以进入上下文，影响本次输出，但这不等于重新训练。",
          "reasonParts": [
            {
              "text": "该表述与r2一致：提示词、历史对话、检索到的资料和工具返回可以进入上下文，影响本次输出，但这不等于重新训练。",
              "evidenceIds": ["r2"]
            }
          ]
        },
        {
          "id": "D",
          "text": "扩展上下文窗口能自动保证其中的信息被正确利用。",
          "reasonParts": [
            {
              "text": "该表述错误，因为r2指出扩大上下文能容纳更多信息，但不会自动保证信息被正确利用。",
              "evidenceIds": ["r2"]
            }
          ]
        }
      ],
      "correctOptionId": "A",
      "reviewCheck": {
        "objectiveIds": ["llm-theory-practice"],
        "role": "concept",
        "rationale": "本题检查学生是否能区分推理阶段使用当前输入与训练阶段更新参数，识别普通对话不会自动更新模型的常见误解，并理解上下文信息进入本次输出并非重新训练。这属于llm-theory-practice目标中concept角色所要求的区分token、训练参数调整与推理时参数是否更新。r2为本题依据来源段，与目标sourceReferenceIds相交。"
      }
    },
    {
      "focus": "区分程序、workflow与Agent的概念和相互关系",
      "scenario": null,
      "stem": "关于程序、workflow和Agent的关系与边界，以下哪项符合课程表述？",
      "kind": "concept",
      "stemEvidenceIds": ["r4", "r5", "r6"],
      "options": [
        {
          "id": "A",
          "text": "程序、workflow和Agent不是三个互斥的产品类别；Agent本身由程序实现，可以处在workflow中的一个步骤，也可以调用一个固定workflow作为工具。",
          "reasonParts": [
            {
              "text": "该表述与r6一致：程序、workflow和Agent不是三个互斥的产品类别；Agent本身由程序实现，可以处在workflow中的一个步骤，也可以调用一个固定workflow作为工具。",
              "evidenceIds": ["r6"]
            }
          ]
        },
        {
          "id": "B",
          "text": "workflow下一步通常由预先设计的流程与条件决定；它可以含有模型节点，也可以完全不使用模型。",
          "reasonParts": [
            {
              "text": "该表述与r4一致：workflow是组织步骤、条件、分支和数据流的方式；下一步通常由预先设计的流程与条件决定；workflow可以含有模型节点，也可以完全不使用模型。",
              "evidenceIds": ["r4"]
            }
          ]
        },
        {
          "id": "C",
          "text": "Agent指围绕目标持续观察状态、选择行动、调用获准工具、接收真实结果并调整后续行动的执行方式。",
          "reasonParts": [
            {
              "text": "该表述与r5一致：Agent指围绕目标持续观察状态、选择行动、调用获准工具、接收真实结果并调整后续行动的执行方式。",
              "evidenceIds": ["r5"]
            }
          ]
        },
        {
          "id": "D",
          "text": "含有一个大模型调用就自动使整个workflow变成Agent。",
          "reasonParts": [
            {
              "text": "该表述错误，因为r4指出workflow含有一个大模型调用并不自动使它成为Agent。",
              "evidenceIds": ["r4"]
            }
          ]
        }
      ],
      "correctOptionId": "A",
      "reviewCheck": {
        "objectiveIds": ["llm-theory-practice"],
        "role": "concept",
        "rationale": "本题检查学生对程序、workflow和Agent这三个概念及其边界的理解，尤其是Agent本身由程序实现、可以与workflow结合，以及含模型调用不自动等于Agent。这符合llm-theory-practice目标中concept角色对基础概念的区分与常见误解识别要求。r4、r5、r6提供了三者定义与关系的事实依据，并与目标sourceReferenceIds相交。"
      }
    }
  ]
}
